function leerArn(arn) {
  const p = arn.split(':');
  if (p[0] !== 'arn' || p.length < 6) return { error: 'no tiene forma de ARN' };
  const [, particion, servicio, region, cuenta, ...resto] = p;
  return { particion, servicio, region: region || '(sin región)', cuenta: cuenta || '(sin cuenta)', recurso: resto.join(':') };
}
const ejemplos = [
  'arn:aws:ec2:sa-east-1:123456789012:instance/i-0abc1234',
  'arn:aws:s3:::bucket-de-ejemplo',
  'arn:aws:iam::123456789012:role/rol-de-lectura',
  'arn:aws:lambda:sa-east-1:123456789012:function:resumen-diario',
];
for (const a of ejemplos) {
  const r = leerArn(a);
  console.log(a);
  console.log('  servicio=' + r.servicio + ' | región=' + r.region + ' | cuenta=' + r.cuenta + ' | recurso=' + r.recurso);
}
