// Precios de lista en USD, leídos de la lista oficial de precios de AWS el 16-11-2026 (Linux, bajo demanda, sin impuestos).
const precios = {
  'sa-east-1 (São Paulo)': { instHora: 0.0168, gbAlmacen: 0.0405, gbSalida: 0.150 },
  'us-east-1 (N. Virginia)': { instHora: 0.0104, gbAlmacen: 0.023, gbSalida: 0.090 },
};
const caso = { horas: 730, gbGuardados: 100, gbSalida: 50 }; // una t3.micro prendida todo el mes, 100 GB en S3 Standard, 50 GB hacia internet
const total = {};
for (const [region, p] of Object.entries(precios)) {
  const cómputo = p.instHora * caso.horas;
  const almacen = p.gbAlmacen * caso.gbGuardados;
  const salida = p.gbSalida * caso.gbSalida;
  total[region] = cómputo + almacen + salida;
  console.log(region.padEnd(26) + ' cómputo ' + cómputo.toFixed(2) + ' | S3 ' + almacen.toFixed(2) + ' | salida ' + salida.toFixed(2) + ' | total USD ' + total[region].toFixed(2));
}
const [a, b] = Object.values(total);
console.log('São Paulo cuesta ' + ((a / b - 1) * 100).toFixed(0) + ' % más que Virginia en este caso.');
